// 2.0版本
class Watermark {
  constructor(options = {}) {
    this.options = {
      container: document.body,
      text: "Watermark",
      base64: "",
      width: 200,
      height: 150,
      font: "16px sans-serif",
      fillStyle: "rgba(0, 0, 0, 0.1)",
      rotate: -20,
      zIndex: 9999,
      id: "__watermark_container__",
      ...options,
    };

    this._observer = null; // 防篡改/防删除
    this._initing = false; // 防止重复初始化
    this._init();
  }

  async _init() {
    if (this._initing) return;
    this._initing = true;

    // 移除旧的水印
    this.remove();

    // 创建水印容器
    const wmDiv = await this._createWatermark();

    // 再次确保清除（防止异步中产生新水印）
    this.remove();

    // 挂载到容器
    this.options.container.appendChild(wmDiv);

    // 防篡改/防删除
    this._observe(wmDiv);
  }
  // 创建水印容器
  async _createWatermark() {
    const { text, base64, width, height, font, fillStyle, rotate, zIndex, id } =
      this.options;

    // 创建canvas生成背景图
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext("2d");

    if (base64) {
      await new Promise((resolve, reject) => {
        const img = new Image();
        img.src = base64;
        img.crossOrigin = "anonymous"; // 跨域兼容（如果是外部图像）
        img.onload = () => {
          ctx.clearRect(0, 0, width, height);
          ctx.save();
          ctx.translate(width / 2, height / 2);
          ctx.rotate((Math.PI / 180) * rotate);
          ctx.drawImage(img, -img.width / 2, -img.height / 2);
          ctx.restore();
          resolve();
        };
        img.onerror = reject;
      });
    } else {
      ctx.clearRect(0, 0, width, height);
      ctx.save();
      ctx.translate(width / 2, height / 2);
      ctx.rotate((Math.PI / 180) * rotate);
      ctx.font = font;
      ctx.fillStyle = fillStyle;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(text, 0, 0);
      ctx.restore();
      return this._wrapDiv(canvas.toDataURL());
    }

    return this._wrapDiv(canvas.toDataURL());
  }

  // 创建水印容器
  _wrapDiv(dataUrl) {
    const { container, zIndex, id } = this.options;

    const div = document.createElement("div");
    div.id = id;
    div.setAttribute(
      "style",
      `
      position: absolute;
      top: 0;
      left: 0;
      width: ${container.scrollWidth}px;
      height: ${container.scrollHeight}px;
      pointer-events: none;
      background-repeat: repeat;
      background-image: url('${dataUrl}');
      z-index: ${zIndex};
    `
    );
    return div;
  }
  // 设置水印背景图
  _setWatermarkBg(dataUrl) {
    const wmDiv = document.getElementById(this.options.id);
    if (wmDiv) {
      wmDiv.style.backgroundImage = `url('${dataUrl}')`;
    }
  }

  // 监控水印元素
  _observe(wmNode) {
    if (!window.MutationObserver) return;

    this._observer = new MutationObserver(() => {
      const existing = document.getElementById(this.options.id);
      if (!existing) {
        console.warn("水印被删除，已重新创建");
        this._init();
      }
    });

    this._observer.observe(this.options.container, {
      childList: true,
      subtree: true,
    });

    // 防止属性被篡改
    const styleObserver = new MutationObserver(() => {
      const wm = document.getElementById(this.options.id);
      if (wm) {
        const expected = this._wrapDiv("").getAttribute("style");
        if (wm.getAttribute("style") !== expected) {
          console.warn("水印样式被修改，已恢复");
          this._init();
        }
      }
    });

    styleObserver.observe(wmNode, {
      attributes: true,
      attributeFilter: ["style"],
    });
  }

  // 移除水印
  remove() {
    const { id } = this.options;
    const elements = document.querySelectorAll(`#${id}`);
    elements.forEach(el => el.remove());
    // const wm = document.getElementById(id);
    // if (wm && wm.parentNode) {
    //   wm.parentNode.removeChild(wm);
    // }
    if (this._observer) {
      this._observer.disconnect();
      this._observer = null;
    }
  }

  // 更新水印
  update(newOptions = {}) {
    this.options = { ...this.options, ...newOptions };
    this._init();
  }
}

export default Watermark;
